create extension if not exists pgcrypto;
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 160),created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,manager_id uuid references public.profiles(id) on delete set null,role text not null check(role in ('manager','employee')),full_name text not null check(length(full_name) between 1 and 120),email text not null,phone text,title text,department text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id));
create table public.daily_reports(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,report_date date not null,title text not null check(length(title) between 1 and 180),description text not null default '',activity_type text not null default 'سایر',activity_weight numeric not null default 3 check(activity_weight between 1 and 5),completion numeric not null check(completion between 0 and 100),quality numeric not null check(quality between 0 and 100),impact numeric not null check(impact between 0 and 100),timeliness numeric not null check(timeliness between 0 and 100),score numeric generated always as (round((completion*.20+quality*.35+impact*.30+timeliness*.15)::numeric,1)) stored,manager_score numeric check(manager_score between 0 and 100),manager_feedback text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,report_date),foreign key(user_id,organization_id) references public.profiles(id,organization_id) on delete cascade);
create table public.report_items(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.daily_reports(id) on delete cascade,activity_type text not null,weight numeric not null check(weight between 1 and 5),title text not null,description text not null default '',created_at timestamptz not null default now());
create table public.voice_reports(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.daily_reports(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,storage_path text not null unique,transcript text,summary text,suggested_score numeric check(suggested_score between 0 and 100),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.strengths(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.daily_reports(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,content text not null check(length(content)<=1000),created_at timestamptz not null default now());
create table public.challenges(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.daily_reports(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,content text not null check(length(content)<=1000),created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,title text not null,body text not null default '',read_at timestamptz,created_at timestamptz not null default now());
create index profiles_manager_idx on public.profiles(manager_id);create index profiles_org_idx on public.profiles(organization_id);create index reports_user_date_idx on public.daily_reports(user_id,report_date desc);create index reports_org_date_idx on public.daily_reports(organization_id,report_date desc);create index items_report_idx on public.report_items(report_id);create index voice_report_idx on public.voice_reports(report_id);create index strengths_report_idx on public.strengths(report_id);create index challenges_report_idx on public.challenges(report_id);create index notifications_user_idx on public.notifications(user_id,created_at desc);
create or replace function public.score_report(p_completion numeric,p_quality numeric,p_impact numeric,p_timeliness numeric) returns numeric language sql immutable as $$ select round((p_completion*.20+p_quality*.35+p_impact*.30+p_timeliness*.15)::numeric,1) $$;
create or replace function public.touch_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end $$;
create trigger profiles_updated before update on public.profiles for each row execute function public.touch_updated_at();create trigger reports_updated before update on public.daily_reports for each row execute function public.touch_updated_at();create trigger voice_updated before update on public.voice_reports for each row execute function public.touch_updated_at();
create or replace function public.is_manager_of(p_employee uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.profiles m join public.profiles e on e.organization_id=m.organization_id where m.id=auth.uid() and m.role='manager' and e.id=p_employee and e.manager_id=m.id) $$;
create or replace function public.current_org() returns uuid language sql stable security definer set search_path=public,auth as $$ select organization_id from public.profiles where id=auth.uid() $$;
create or replace function public.same_org(p_org uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.profiles p where p.id=auth.uid() and p.organization_id=p_org) $$;
create or replace function public.guard_report_owner() returns trigger language plpgsql security definer set search_path=public as $$ declare r public.daily_reports; begin select * into r from public.daily_reports where id=new.report_id; if r.id is null or r.user_id<>new.user_id or r.organization_id<>(select organization_id from public.profiles where id=new.user_id) then raise exception 'invalid report ownership'; end if; return new; end $$;
create trigger item_owner before insert or update on public.report_items for each row execute function public.guard_report_owner();create trigger voice_owner before insert or update on public.voice_reports for each row execute function public.guard_report_owner();create trigger strengths_owner before insert or update on public.strengths for each row execute function public.guard_report_owner();create trigger challenges_owner before insert or update on public.challenges for each row execute function public.guard_report_owner();
create or replace function public.guard_report_update() returns trigger language plpgsql set search_path=public as $$ begin if auth.uid()=old.user_id then if new.user_id<>old.user_id or new.organization_id<>old.organization_id or new.manager_score is distinct from old.manager_score or new.manager_feedback is distinct from old.manager_feedback then raise exception 'not authorized to change evaluation'; end if; elsif public.is_manager_of(old.user_id) then if new.user_id<>old.user_id or new.organization_id<>old.organization_id or new.report_date<>old.report_date or new.title<>old.title or new.description<>old.description or new.activity_type<>old.activity_type or new.activity_weight<>old.activity_weight or new.completion<>old.completion or new.quality<>old.quality or new.impact<>old.impact or new.timeliness<>old.timeliness then raise exception 'manager may only change evaluation'; end if; else raise exception 'not authorized'; end if; return new; end $$;
create trigger report_update_guard before update on public.daily_reports for each row execute function public.guard_report_update();
create or replace function public.manager_team_stats() returns table(report_count bigint,average_score numeric) language sql stable security definer set search_path=public,auth as $$ select count(*),round(avg(coalesce(r.manager_score,r.score)),1) from public.daily_reports r join public.profiles e on e.id=r.user_id join public.profiles m on m.id=auth.uid() where m.role='manager' and e.manager_id=m.id and e.organization_id=m.organization_id $$;
revoke all on function public.manager_team_stats() from public;grant execute on function public.manager_team_stats() to authenticated;
alter table public.organizations enable row level security;alter table public.profiles enable row level security;alter table public.daily_reports enable row level security;alter table public.report_items enable row level security;alter table public.voice_reports enable row level security;alter table public.strengths enable row level security;alter table public.challenges enable row level security;alter table public.notifications enable row level security;
create policy org_read on public.organizations for select to authenticated using(public.same_org(id));
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or (organization_id=public.current_org() and public.is_manager_of(id)));
create policy profiles_self_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid() and role=(select role from public.profiles where id=auth.uid()) and organization_id=public.current_org() and manager_id is not distinct from (select p.manager_id from public.profiles p where p.id=auth.uid()));
create policy reports_read on public.daily_reports for select to authenticated using(user_id=auth.uid() or public.is_manager_of(user_id));
create policy reports_insert on public.daily_reports for insert to authenticated with check(user_id=auth.uid() and organization_id=public.current_org());
create policy reports_update_employee on public.daily_reports for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and organization_id=public.current_org());
create policy reports_update_manager on public.daily_reports for update to authenticated using(public.is_manager_of(user_id)) with check(public.is_manager_of(user_id));
create policy items_read on public.report_items for select to authenticated using(exists(select 1 from public.daily_reports r where r.id=report_id and (r.user_id=auth.uid() or public.is_manager_of(r.user_id))));
create policy items_insert on public.report_items for insert to authenticated with check(exists(select 1 from public.daily_reports r where r.id=report_id and r.user_id=auth.uid()));
create policy items_update_delete on public.report_items for all to authenticated using(exists(select 1 from public.daily_reports r where r.id=report_id and r.user_id=auth.uid())) with check(exists(select 1 from public.daily_reports r where r.id=report_id and r.user_id=auth.uid()));
create policy voice_read on public.voice_reports for select to authenticated using(user_id=auth.uid() or public.is_manager_of(user_id));create policy voice_insert on public.voice_reports for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.daily_reports r where r.id=report_id and r.user_id=auth.uid()));create policy voice_owner_update on public.voice_reports for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy strengths_access on public.strengths for all to authenticated using(user_id=auth.uid() or public.is_manager_of(user_id)) with check(user_id=auth.uid() and exists(select 1 from public.daily_reports r where r.id=report_id and r.user_id=auth.uid()));create policy challenges_access on public.challenges for all to authenticated using(user_id=auth.uid() or public.is_manager_of(user_id)) with check(user_id=auth.uid() and exists(select 1 from public.daily_reports r where r.id=report_id and r.user_id=auth.uid()));
create policy notifications_read on public.notifications for select to authenticated using(user_id=auth.uid());create policy notifications_update on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('report-audio','report-audio',false,26214400,array['audio/webm','audio/mpeg','audio/mp4','audio/wav','audio/ogg','audio/x-m4a']) on conflict(id) do nothing;
create policy audio_read_private on storage.objects for select to authenticated using(bucket_id='report-audio' and ( (storage.foldername(name))[2]=auth.uid()::text or public.is_manager_of(((storage.foldername(name))[2])::uuid)));
create policy audio_upload_private on storage.objects for insert to authenticated with check(bucket_id='report-audio' and (storage.foldername(name))[2]=auth.uid()::text and exists(select 1 from public.profiles p where p.id=auth.uid() and p.organization_id=(storage.foldername(name))[1]::uuid));
create policy audio_delete_owner on storage.objects for delete to authenticated using(bucket_id='report-audio' and (storage.foldername(name))[2]=auth.uid()::text);
